import React, { useEffect, useState } from "react";
import api from "../services/api";

const formatResourceLabel = (resource) =>
  resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;

const BookingForm = ({
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  availabilityMsg,
  loading
}) => {
  const [blocks, setBlocks] = useState([]);
  const [resources, setResources] = useState([]);
  const [blocksLoading, setBlocksLoading] = useState(false);
  const [resourceLoading, setResourceLoading] = useState(false);

  useEffect(() => {
    const fetchBlocks = async () => {
      setBlocksLoading(true);
      try {
        const response = await api.get("/blocks");
        setBlocks(response.data || []);
      } catch {
        setBlocks([]);
      } finally {
        setBlocksLoading(false);
      }
    };

    fetchBlocks();
  }, []);

  useEffect(() => {
    const fetchResources = async () => {
      if (formData.resourceScope === "block" && !formData.blockId) {
        setResources([]);
        return;
      }

      setResourceLoading(true);
      try {
        const response =
          formData.resourceScope === "extra"
            ? await api.get("/extra-centers")
            : await api.get(`/blocks/${formData.blockId}/resources`);
        setResources(response.data || []);
      } catch {
        setResources([]);
      } finally {
        setResourceLoading(false);
      }
    };

    fetchResources();
  }, [formData.blockId, formData.resourceScope]);

  const handleScopeChange = (value) => {
    onChange({ target: { name: "resourceScope", value } });
    onChange({ target: { name: "blockId", value: "" } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const handleBlockChange = (event) => {
    onChange({ target: { name: "blockId", value: event.target.value } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const scopeIsBlock = formData.resourceScope === "block";

  return (
    <div className="panel-card booking-card-shell">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Pick a block or extra center, choose a resource, and reserve your slot.</p>
        </div>
      </div>

      <div className="scope-toggle">
        <button
          type="button"
          className={`scope-chip ${scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("block")}
        >
          Block
        </button>
        <button
          type="button"
          className={`scope-chip ${!scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("extra")}
        >
          Extra Centers
        </button>
      </div>

      <form className="grid-form" onSubmit={onSubmit}>
        {scopeIsBlock ? (
          <label>
            <span>Block</span>
            <select value={formData.blockId || ""} onChange={handleBlockChange} required>
              <option value="">{blocksLoading ? "Loading blocks..." : "Select block"}</option>
              {blocks.map((block) => (
                <option key={block.id} value={block.id}>
                  Block {block.name}
                </option>
              ))}
            </select>
          </label>
        ) : (
          <div className="selection-summary">
            <span>Extra Centers</span>
            <p>Book shared spaces like the Innovation Center or Main Seminar Hall.</p>
          </div>
        )}

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId || ""}
            onChange={onChange}
            required
            disabled={scopeIsBlock ? !formData.blockId : false}
          >
            <option value="">
              {scopeIsBlock && !formData.blockId
                ? "Select block first"
                : resourceLoading
                ? "Loading resources..."
                : resources.length === 0
                ? "No resources found"
                : "Select resource"}
            </option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {formatResourceLabel(resource)}
              </option>
            ))}
          </select>
        </label>

        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={formData.bookingDate || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>Start time</span>
          <input
            type="time"
            name="startTime"
            value={formData.startTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>End time</span>
          <input
            type="time"
            name="endTime"
            value={formData.endTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose || ""}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck}>
            Check Availability
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>

        {availabilityMsg ? (
          <div className="alert-box full-width">
            {typeof availabilityMsg === "object" ? JSON.stringify(availabilityMsg) : availabilityMsg}
          </div>
        ) : null}
      </form>
    </div>
  );
};

export default BookingForm;
